documentCanvasContent:
'use client'

import { useRef, useCallback } from 'react'
import dynamic from 'next/dynamic'
import Header from '../header/header'
import Sidebar from '../sidebar/sidebar'
import ProposalFields from '../suggestions/ProposalFields'
import OpenSuggestionsPanel from '../suggestions/OpenSuggestionsPanel'
import ApplySuggestions from '../suggestions/ApplySuggestions'

// The TipTap editor (via @veltdev/tiptap-velt-comments) touches browser-only
// APIs at module-load and isn't SSR-safe, so load it client-only.
const TipTapComponent = dynamic(() => import('./TipTapComponent'), { ssr: false })

export default function DocumentCanvas() {
  // Single scroll container owned here so TipTap's add-comment flow can
  // preserve scroll position (it reads scrollContainerRef.current.scrollTop)
  // and the Table of Contents sidebar can jump between headings inside it.
  const scrollContainerRef = useRef<HTMLDivElement>(null)

  const scrollToHeading = useCallback((headingText: string) => {
    if (!scrollContainerRef.current) return

    const headings = scrollContainerRef.current.querySelectorAll('h1, h2, h3')
    const targetHeading = Array.from(headings).find(
      (heading) => heading.textContent?.toLowerCase().trim() === headingText.toLowerCase().trim()
    )

    if (targetHeading) {
      const containerRect = scrollContainerRef.current.getBoundingClientRect()
      const headingRect = targetHeading.getBoundingClientRect()
      const scrollTop = headingRect.top - containerRect.top + scrollContainerRef.current.scrollTop

      scrollContainerRef.current.scrollTo({
        top: scrollTop - 50,
        behavior: 'smooth',
      })
    }
  }, [])

  return (
    <div className="w-full h-screen relative" style={{ backgroundColor: 'var(--app-bg)' }}>
      <Header />

      <div ref={scrollContainerRef} className="h-screen overflow-y-auto">
        <div className="flex justify-center pt-[64px] px-4 pb-28">
          {/* Editor (flex-1) left, narrow approval rail right. The pair is
              centered and capped, so the editor sits left-of-center. */}
          <div className="w-full max-w-[1284px] flex items-start gap-6">
            {/* LEFT: proposal fields + editor, stacked */}
            <div className="flex-1 min-w-0 max-w-[820px] flex flex-col gap-5">
              <ProposalFields />
              <TipTapComponent scrollContainerRef={scrollContainerRef} />
              {/* Below lg the sticky rail is hidden; show the panel stacked here */}
              <div className="lg:hidden">
                <OpenSuggestionsPanel />
              </div>
            </div>

            {/* RIGHT: narrow approval rail. sticky so it stays in view while the
                long body scrolls; top offset clears the Header icon cluster. */}
            <div className="hidden lg:block w-[440px] shrink-0 sticky top-[56px] self-start">
              <OpenSuggestionsPanel />
            </div>
          </div>
        </div>
      </div>

      <div className="absolute top-0 left-0 z-10">
        <Sidebar onScrollToHeading={scrollToHeading} />
      </div>

      {/* Renderless: applies approved suggestions / reverts rejected ones. */}
      <ApplySuggestions />
    </div>
  )
}

tipTapComponentContent:
'use client'

import { EditorContent, useEditor } from '@tiptap/react'
import { BubbleMenu } from '@tiptap/react/menus'
import StarterKit from '@tiptap/starter-kit'
import TextAlign from '@tiptap/extension-text-align'
import Underline from '@tiptap/extension-underline'
import { useEffect } from 'react'
import {
  useCommentAnnotations,
  useSuggestionModeState,
} from '@veltdev/react' // [Velt] Comments + Suggestions hooks
import { TiptapVeltComments, addComment, renderComments } from '@veltdev/tiptap-velt-comments' // [Velt] TipTap extension and utilities for integrating Velt comments into the editor
import { BubbleMenuToolbar } from './ui/BubbleMenuToolbar'
import { TipTapComponentProps } from './types'
import { initialContent } from './constants'
// [Velt] Inline per-edit suggestion engine for the body (Google-Docs style):
// each edit is wrapped in deletion (strikethrough) / insertion (underline) marks
// and committed as its own Velt suggestion carrying the real old → new diff.
import { SuggestionExtensions, VeltSuggestionBridge } from './suggestion'

export default function TipTapComponent({ scrollContainerRef }: TipTapComponentProps) {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        // Real block headings (h1–h3). Inline styled-span "headings" were the
        // source of a track-changes bug: editing text inside a styled inline
        // span makes the browser emit a whole-span replace per keystroke, which
        // the suggestion engine captured as "delete entire heading → reinsert".
        heading: { levels: [1, 2, 3] },
      }),
      TextAlign.configure({
        types: ['paragraph', 'heading'],
      }),
      Underline,
      TiptapVeltComments, // [Velt] Registers TipTap extension that enables comment markers and selection tracking in the editor
      ...SuggestionExtensions(), // [Velt] Inline suggestion marks + ProseMirror plugin (tracks each body edit)
    ],
    content: initialContent,
    immediatelyRender: false, // Prevents SSR hydration mismatches by only rendering on client
  })

  const commentAnnotations = useCommentAnnotations() // [Velt] Subscribes to comment data changes and returns array of all active comment annotations

  useEffect(() => {
    if (editor && commentAnnotations?.length) {
      renderComments({ editor, commentAnnotations }) // [Velt] Renders comment highlights and markers in the editor based on annotation positions
    }
  }, [editor, commentAnnotations])

  // Subtle accent while suggesting mode is on (always on in this demo). Per-edit
  // pending state is shown inline (dashed strikethrough/underline), not as a
  // whole-body badge.
  const suggesting = useSuggestionModeState() ?? false

  const addTiptapVeltComment = () => {
    if (editor) {
      // Preserve scroll position across Velt comment creation
      const scrollContainer = scrollContainerRef?.current
      const scrollTop = scrollContainer?.scrollTop ?? 0
      addComment({ editor }) // [Velt] Triggers comment creation flow on selected text in the editor
      if (scrollContainer) {
        requestAnimationFrame(() => {
          scrollContainer.scrollTop = scrollTop
        })
      }
    }
  }

  return (
    <div className="w-full" data-name="Tiptap / Suggestions Body">
      {/* [Velt] Renderless: enables the inline suggestion plugin, sets the
          author, debounce-commits each edit as a suggestion, and applies/reverts
          inline marks on accept/reject. */}
      <VeltSuggestionBridge editor={editor} />

      <div
        className="relative border border-solid rounded-[16px] p-[42px_56px_56px_56px] min-h-[460px] transition-shadow"
        style={{
          backgroundColor: 'var(--app-surface)',
          borderColor: suggesting ? '#6366f1' : 'var(--app-surface-border)',
          boxShadow: suggesting ? '0 0 0 1px rgba(99,102,241,0.45)' : 'none',
        }}
      >
        <EditorContent
          editor={editor}
          className="tiptap-editor-content prose prose-invert max-w-none"
        />

        {editor && (
          <BubbleMenu editor={editor} options={{ placement: 'top', offset: 8 }}>
            <BubbleMenuToolbar editor={editor} onAddComment={addTiptapVeltComment} />
          </BubbleMenu>
        )}
      </div>
    </div>
  )
}

