suggestionsTypesContent:
// Shared model for the "proposal document" metadata fields that act as
// Velt Suggestion targets. Each field is tagged with
// `data-velt-suggestion-target="<targetId>"` so the Suggestions SDK can
// capture before/after values when suggestion mode is on.

export type Proposal = {
  title: string
  status: string
  category: string
  publishDate: string
}

// Stable, app-owned target ids — reused as the React state keys (NOT random
// UUIDs, which would change across re-renders and break matching).
// `body` is the TipTap editor itself (registered via a getter in
// TipTapComponent), so the whole rich-text body can be proposed too.
export const TARGET = {
  title: 'proposal.title',
  status: 'proposal.status',
  category: 'proposal.category',
  publishDate: 'proposal.publishDate',
  body: 'proposal.body',
} as const

export const FIELD_LABEL: Record<string, string> = {
  [TARGET.title]: 'Title',
  [TARGET.status]: 'Status',
  [TARGET.category]: 'Category',
  [TARGET.publishDate]: 'Publish date',
  [TARGET.body]: 'Article body',
}

export const STATUS_OPTIONS = ['Draft', 'In Review', 'Approved', 'Published']
export const CATEGORY_OPTIONS = ['Engineering', 'Product', 'Design', 'Marketing', 'Company']

export const INITIAL_PROPOSAL: Proposal = {
  title: 'Building Real-Time Collaboration with Velt',
  status: 'Draft',
  category: 'Engineering',
  publishDate: '2026-07-01',
}

// Maps a Velt suggestion target onto the matching field of local state.
// Centralizing the switch lets the approve / reject handlers share it — they
// only differ in which value (newValue vs oldValue) they pass in.
export function writeProposalField(
  prev: Proposal,
  targetId: string,
  value: unknown,
): Proposal {
  switch (targetId) {
    case TARGET.title:
      return { ...prev, title: String(value) }
    case TARGET.status:
      return { ...prev, status: String(value) }
    case TARGET.category:
      return { ...prev, category: String(value) }
    case TARGET.publishDate:
      return { ...prev, publishDate: String(value) }
    default:
      return prev
  }
}

proposalContextContent:
'use client'

import { createContext, useContext, useState, useCallback } from 'react'
import type { ReactNode } from 'react'
import { Proposal, INITIAL_PROPOSAL, writeProposalField } from './types'

type ProposalContextValue = {
  proposal: Proposal
  // Idempotent setter: always sets the field to `value` (never increments),
  // so it's safe to run repeatedly across reconnects / multiple tabs — the
  // contract Velt's suggestionApproved handler expects.
  writeField: (targetId: string, value: unknown) => void
}

const ProposalContext = createContext<ProposalContextValue | undefined>(undefined)

export function ProposalProvider({ children }: { children: ReactNode }) {
  const [proposal, setProposal] = useState<Proposal>(INITIAL_PROPOSAL)

  const writeField = useCallback((targetId: string, value: unknown) => {
    setProposal((prev) => writeProposalField(prev, targetId, value))
  }, [])

  return (
    <ProposalContext.Provider value={{ proposal, writeField }}>
      {children}
    </ProposalContext.Provider>
  )
}

export function useProposal(): ProposalContextValue {
  const ctx = useContext(ProposalContext)
  if (!ctx) {
    throw new Error('useProposal must be used within a ProposalProvider')
  }
  return ctx
}

proposalFieldsContent:
'use client'

import type { CSSProperties } from 'react'
import { usePendingSuggestion, useSuggestionModeState } from '@veltdev/react'
import { useProposal } from './ProposalContext'
import { TARGET, STATUS_OPTIONS, CATEGORY_OPTIONS } from './types'

/**
 * The "article metadata" card. Every control is tagged with
 * `data-velt-suggestion-target` so that — when suggestion mode is on — editing
 * a field and blurring it creates a pending Velt Suggestion (old → new) instead
 * of a silent write. The rich-text body below (TipTap) stays the comments
 * surface; these structured fields are the suggestion surface.
 */
export default function ProposalFields() {
  const { proposal, writeField } = useProposal()

  return (
    <div style={S.card}>
      <div style={S.sectionLabel}>Article details</div>

      <Field
        kind="input"
        label="Title"
        targetId={TARGET.title}
        value={proposal.title}
        onChange={(v) => writeField(TARGET.title, v)}
      />

      <div style={S.row}>
        <Field
          kind="select"
          label="Status"
          targetId={TARGET.status}
          options={STATUS_OPTIONS}
          value={proposal.status}
          onChange={(v) => writeField(TARGET.status, v)}
        />
        <Field
          kind="select"
          label="Category"
          targetId={TARGET.category}
          options={CATEGORY_OPTIONS}
          value={proposal.category}
          onChange={(v) => writeField(TARGET.category, v)}
        />
        <Field
          kind="date"
          label="Publish date"
          targetId={TARGET.publishDate}
          value={proposal.publishDate}
          onChange={(v) => writeField(TARGET.publishDate, v)}
        />
      </div>
    </div>
  )
}

// ── Field ───────────────────────────────────────────────────────────────────
// One primitive control. The `data-velt-suggestion-target` attribute goes on
// the form element itself; the SDK reads `.value` at focus and blur to detect a
// change. Controlled inputs (state updates each keystroke) keep `.value` in
// sync, so no `registerTarget` getter is needed for these simple primitives.

type CommonFieldProps = {
  label: string
  targetId: string
  value: string
  onChange: (v: string) => void
}

type FieldProps = CommonFieldProps &
  ({ kind: 'input' | 'date' } | { kind: 'select'; options: string[] })

function Field(props: FieldProps) {
  const { label, targetId, value, onChange, kind } = props
  const suggesting = useSuggestionModeState() ?? false
  const pending = usePendingSuggestion(targetId)

  return (
    <label style={S.field}>
      <span style={S.fieldLabel}>{label}</span>
      <div style={S.fieldWrap}>
        {kind === 'input' && (
          <input
            type="text"
            data-velt-suggestion-target={targetId}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            style={controlStyle(suggesting, !!pending)}
          />
        )}

        {kind === 'select' && (
          <select
            data-velt-suggestion-target={targetId}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            style={controlStyle(suggesting, !!pending)}
          >
            {props.options.map((o) => (
              <option key={o} value={o}>
                {o}
              </option>
            ))}
          </select>
        )}

        {kind === 'date' && (
          <input
            type="date"
            data-velt-suggestion-target={targetId}
            value={value}
            onChange={(e) => onChange(e.target.value)}
            style={controlStyle(suggesting, !!pending)}
          />
        )}

        {pending && (
          <span style={S.pendingPill} title={pending.summary ?? undefined}>
            PENDING
          </span>
        )}
      </div>
    </label>
  )
}

const ACCENT = '#6366f1'
const ACCENT_DIM = 'rgba(99,102,241,0.10)'
const WARN = '#f59e0b'
const WARN_DIM = 'rgba(245,158,11,0.12)'

function controlStyle(suggesting: boolean, pending: boolean): CSSProperties {
  const base: CSSProperties = {
    width: '100%',
    boxSizing: 'border-box',
    padding: '8px 10px',
    border: '1px solid var(--app-surface-border)',
    borderRadius: 8,
    fontSize: 13,
    fontFamily: 'inherit',
    color: 'var(--app-text-primary)',
    background: 'var(--app-bg)',
    outline: 'none',
    transition: 'border-color .15s, background .15s',
  }
  if (pending) return { ...base, border: `1px dashed ${WARN}`, background: WARN_DIM }
  if (suggesting) return { ...base, border: `1px solid ${ACCENT}`, background: ACCENT_DIM }
  return base
}

const S: Record<string, CSSProperties> = {
  card: {
    background: 'var(--app-surface)',
    border: '1px solid var(--app-surface-border)',
    borderRadius: 16,
    padding: '20px 24px 24px',
  },
  sectionLabel: {
    fontSize: 11,
    fontWeight: 600,
    color: 'var(--app-text-tertiary)',
    textTransform: 'uppercase',
    letterSpacing: '.1em',
    paddingBottom: 12,
    marginBottom: 16,
    borderBottom: '1px solid var(--app-surface-border)',
  },
  row: { display: 'flex', gap: 14, flexWrap: 'wrap' },
  field: { display: 'block', marginBottom: 14, flex: '1 1 160px' },
  fieldLabel: {
    display: 'block',
    fontSize: 12,
    fontWeight: 500,
    color: 'var(--app-text-secondary)',
    marginBottom: 6,
  },
  fieldWrap: { position: 'relative' },
  pendingPill: {
    position: 'absolute',
    top: 8,
    right: 8,
    background: WARN,
    color: '#1a1205',
    fontSize: 9,
    fontWeight: 700,
    padding: '2px 7px',
    borderRadius: 4,
    pointerEvents: 'none',
    letterSpacing: '.08em',
  },
}

suggestionModeIndicatorContent:
'use client'

import { useEffect } from 'react'
import { useEnableSuggestionMode, useVeltClient } from '@veltdev/react'
import type { TargetEditDetails } from '@veltdev/types'
import { FIELD_LABEL } from './types'

/**
 * This demo runs in suggestion mode only — there is no "editing" mode. We
 * enable suggestion mode as soon as the Velt client is ready and keep it on, so
 * every edit to a tagged field becomes a proposed change. (The article body is
 * handled separately by the inline Tiptap suggestion engine.) The badge is
 * purely informational (not a toggle).
 */
export default function SuggestionModeIndicator() {
  const { client } = useVeltClient()
  const { enableSuggestionMode } = useEnableSuggestionMode()

  useEffect(() => {
    if (!client) return
    enableSuggestionMode({
      onTargetEditCommit: ({ targetId, oldValue, newValue }: TargetEditDetails) => {
        return {
          summary: `${FIELD_LABEL[targetId] ?? targetId}: "${String(oldValue)}" → "${String(newValue)}"`,
        }
      },
    })
  }, [client, enableSuggestionMode])

  return (
    <span
      title="Every edit is captured as a suggestion"
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 7,
        height: 28,
        padding: '0 12px',
        borderRadius: 999,
        border: '1px solid #6366f1',
        background: 'rgba(99,102,241,0.14)',
        color: '#6366f1',
        fontSize: 12,
        fontWeight: 600,
        userSelect: 'none',
      }}
    >
      <span style={{ width: 7, height: 7, borderRadius: 999, background: '#6366f1' }} />
      Suggesting
    </span>
  )
}

openSuggestionsPanelContent:
'use client'

import type { CSSProperties } from 'react'
import { useSuggestions, VeltCommentThread } from '@veltdev/react'
import { FIELD_LABEL, TARGET } from './types'

/**
 * Lists every Suggestion on the document. For each one we show the actual
 * pending change (label + old → new diff, or a summary for the body), then a
 * <VeltCommentThread dialogVariant="suggestion-mode-thread"> for the Accept /
 * Reject actions + discussion. Reviewers act here; the outcome flows to
 * <ApplySuggestions /> (fields) and TipTapComponent (body).
 */
export default function OpenSuggestionsPanel() {
  const suggestions = useSuggestions() ?? []
  const pendingCount = suggestions.filter((s) => s.status === 'pending').length
  // Newest first — sort by creation time descending.
  const ordered = [...suggestions].sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0))

  return (
    <div style={S.card}>
      <div style={S.sectionLabel}>
        Open suggestions{pendingCount ? ` · ${pendingCount} pending` : ''}
      </div>

      {suggestions.length === 0 ? (
        <div style={S.empty}>
          No suggestions yet. Edit a field — or the article body — to propose a
          change; every edit is captured as a <strong>suggestion</strong>.
        </div>
      ) : (
        <ul style={S.list}>
          {ordered.map((s) => (
            <li key={s.annotationId} style={S.listItem}>
              <div style={S.changeHeader}>
                <span style={S.changeLabel}>{labelFor(s)}</span>
                <span style={statusStyle(s.status)}>{s.status}</span>
              </div>

              <div style={S.diff}>
                <Diff s={s} />
              </div>

              <VeltCommentThread
                annotationId={s.annotationId}
                dialogVariant="suggestion-mode-thread"
              />
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

// A suggestion can come from a metadata field (title/status/category/date) or
// from an inline body edit produced by the Tiptap suggestion engine. Inline
// body edits carry `metadata.kind` and the real diff in `metadata.oldValue` /
// `metadata.newValue` (the SDK's top-level oldValue is empty for those).
type SuggestionLike = {
  targetId: string
  oldValue: unknown
  newValue: unknown
  summary: string | null
  metadata?: Record<string, unknown>
}

function isInlineBody(s: SuggestionLike): boolean {
  return typeof s.metadata?.kind === 'string'
}

function labelFor(s: SuggestionLike): string {
  if (isInlineBody(s)) return 'Article body'
  return FIELD_LABEL[s.targetId] ?? s.targetId
}

function Diff({ s }: { s: SuggestionLike }) {
  // Inline body edit — read the real per-edit diff from metadata.
  if (isInlineBody(s)) {
    const kind = String(s.metadata?.kind)
    if (kind === 'format-add' || kind === 'format-remove') {
      return <span style={S.summary}>{s.summary ?? 'Formatting change'}</span>
    }
    const oldV = String(s.metadata?.oldValue ?? '')
    const newV = String(s.metadata?.newValue ?? '')
    return (
      <>
        {oldV && <span style={S.oldValue}>{truncate(oldV)}</span>}
        {oldV && newV && <span style={S.arrow}>→</span>}
        {newV && <span style={S.newValue}>{truncate(newV)}</span>}
      </>
    )
  }
  // Date field — neutral before → after (no strikethrough).
  if (s.targetId === TARGET.publishDate) {
    return (
      <>
        <span style={S.oldValueNeutral}>{truncate(String(s.oldValue))}</span>
        <span style={S.arrow}>→</span>
        <span style={S.newValue}>{truncate(String(s.newValue))}</span>
      </>
    )
  }
  // Text field (title/status/category) — strikethrough old → new.
  return (
    <>
      <span style={S.oldValue}>{truncate(String(s.oldValue))}</span>
      <span style={S.arrow}>→</span>
      <span style={S.newValue}>{truncate(String(s.newValue))}</span>
    </>
  )
}

function truncate(v: string, max = 120): string {
  return v.length > max ? `${v.slice(0, max)}…` : v
}

function statusStyle(status: string): CSSProperties {
  const map: Record<string, { bg: string; fg: string }> = {
    pending: { bg: 'rgba(99,102,241,0.14)', fg: '#6366f1' },
    approved: { bg: 'rgba(25,143,101,0.16)', fg: '#198f65' },
    rejected: { bg: 'rgba(255,113,98,0.16)', fg: '#ff7162' },
    stale: { bg: 'rgba(128,128,128,0.16)', fg: '#9aa0a6' },
    apply_failed: { bg: 'rgba(255,113,98,0.16)', fg: '#ff7162' },
  }
  const c = map[status] ?? map.stale
  return {
    fontSize: 10,
    fontWeight: 700,
    letterSpacing: '.06em',
    textTransform: 'uppercase',
    color: c.fg,
    background: c.bg,
    padding: '2px 8px',
    borderRadius: 999,
  }
}

const S: Record<string, CSSProperties> = {
  card: {
    background: 'var(--app-surface)',
    border: '1px solid var(--app-surface-border)',
    borderRadius: 16,
    padding: '16px 14px 18px',
  },
  sectionLabel: {
    fontSize: 11,
    fontWeight: 600,
    color: 'var(--app-text-tertiary)',
    textTransform: 'uppercase',
    letterSpacing: '.1em',
    paddingBottom: 12,
    marginBottom: 16,
    borderBottom: '1px solid var(--app-surface-border)',
  },
  empty: {
    fontSize: 13,
    color: 'var(--app-text-tertiary)',
    background: 'var(--app-bg)',
    border: '1px dashed var(--app-surface-border)',
    borderRadius: 10,
    padding: '20px 16px',
    textAlign: 'center',
  },
  list: {
    padding: 0,
    margin: 0,
    listStyle: 'none',
    maxHeight: 'calc(100vh - 160px)',
    overflowY: 'auto',
    overflowX: 'hidden',
  },
  listItem: {
    listStyle: 'none',
    border: '1px solid var(--app-surface-border)',
    borderRadius: 12,
    padding: 12,
    marginBottom: 12,
    background: 'var(--app-bg)',
  },
  changeHeader: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 8,
    marginBottom: 8,
  },
  changeLabel: {
    fontSize: 13,
    fontWeight: 600,
    color: 'var(--app-text-primary)',
  },
  diff: {
    display: 'flex',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: 8,
    fontSize: 12,
    marginBottom: 10,
  },
  oldValue: {
    color: 'var(--app-text-tertiary)',
    textDecoration: 'line-through',
    background: 'rgba(255,113,98,0.10)',
    padding: '2px 6px',
    borderRadius: 4,
    overflowWrap: 'anywhere',
    minWidth: 0,
  },
  oldValueNeutral: {
    color: 'var(--app-text-secondary)',
    background: 'var(--app-surface-hover)',
    padding: '2px 6px',
    borderRadius: 4,
    overflowWrap: 'anywhere',
    minWidth: 0,
  },
  arrow: { color: 'var(--app-text-tertiary)' },
  newValue: {
    color: 'var(--app-text-primary)',
    background: 'rgba(25,143,101,0.14)',
    padding: '2px 6px',
    borderRadius: 4,
    fontWeight: 500,
    overflowWrap: 'anywhere',
    minWidth: 0,
  },
