}

applySuggestionsContent:
'use client'

import { useEffect } from 'react'
import { useSuggestionEventCallback } from '@veltdev/react'
import { useProposal } from './ProposalContext'

/**
 * Renderless. The SDK never mutates your data for you — it captures intent and
 * orchestrates review; applying the change is your code's job. Here we listen
 * for the approve / reject outcomes and write the proposal fields accordingly:
 *   - approved → write `newValue`
 *   - rejected → revert to `oldValue`
 */
export default function ApplySuggestions() {
  const { writeField } = useProposal()

  const approved = useSuggestionEventCallback('suggestionApproved')
  const rejected = useSuggestionEventCallback('suggestionRejected')

  useEffect(() => {
    const s = approved?.suggestion
    if (!s) return
    writeField(s.targetId, s.newValue)
  }, [approved, writeField])

  useEffect(() => {
    const s = rejected?.suggestion
    if (!s) return
    writeField(s.targetId, s.oldValue)
  }, [rejected, writeField])

  return null
}

inlineCoreExtensionContent:
import { Extension } from '@tiptap/core';
import {
  SUGGESTION_DELETION_MARK,
  SUGGESTION_INSERTION_MARK,
  SUGGESTION_MARK,
  SuggestionDeletionMark,
  SuggestionInsertionMark,
  SuggestionMark,
  findSuggestionRangesById,
  findSuggestionRangesByPendingId,
  mergeAdjacent,
} from './suggestionMark';
import {
  META_SET_STATE,
  META_SKIP,
  applySuggestionRewrite,
  createInlineSuggestionPlugin,
  suggestionPluginKey,
} from './plugin';
import type { SuggestionAuthor, SuggestionKind, SuggestionMarkAttrs } from './types';

export interface SuggestionMetaOptions {
  enableSuggestReplacement: boolean;
}

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    veltSuggestion: {
      applySuggestionMark: (
        attrs: SuggestionMarkAttrs,
        range: { from: number; to: number },
      ) => ReturnType;
      replaceWithNewValueById: (suggestionId: string) => ReturnType;
      removeMarkById: (suggestionId: string) => ReturnType;
      promotePendingCluster: (
        pendingId: string,
        next: {
          suggestionId: string;
          targetId: string;
          kind: SuggestionKind;
          oldValue: string;
          newValue: string;
        },
      ) => ReturnType;
      setSuggestionPluginEnabled: (enabled: boolean) => ReturnType;
      setSuggestionPluginAuthor: (author: SuggestionAuthor | null) => ReturnType;
    };
  }
}

export const SuggestionMeta = Extension.create<SuggestionMetaOptions>({
  name: 'veltSuggestionMeta',

  addOptions() {
    return {
      enableSuggestReplacement: true,
    };
  },

  addProseMirrorPlugins() {
    return [createInlineSuggestionPlugin()];
  },

  /**
   * Install a dispatchTransaction wrapper on the editor view so the user's
   * steps and our suggestion-marking steps land in PM as a SINGLE transaction.
   * That gives atomic undo/redo for every kind of edit (typing, paste, delete,
   * structural — anything) without the customer having to write any wiring.
   */
  onCreate() {
    const view = this.editor.view;
    const previous = view.props.dispatchTransaction;
    view.setProps({
      dispatchTransaction(tr) {
        // 'this' at runtime is the EditorView, but PM types it loosely. We
        // already captured the view reference via closure; use it.
        const ps = suggestionPluginKey.getState(view.state);
        if (ps) applySuggestionRewrite(tr, view.state, ps);
        if (previous) previous.call(view, tr);
        else view.updateState(view.state.apply(tr));
      },
    });
  },

  addCommands() {
    return {
      applySuggestionMark:
        (attrs, range) =>
        ({ state, tr, dispatch }) => {
          const wrap = state.schema.marks[SUGGESTION_MARK];
          const del = state.schema.marks[SUGGESTION_DELETION_MARK];
          const ins = state.schema.marks[SUGGESTION_INSERTION_MARK];
          if (!wrap || !del || !ins) return false;

          const { from, to } = range;
          const wrappingMark = wrap.create(attrs);
          const newValueText =
            (attrs.newValue ?? '').trim().length > 0 ? attrs.newValue : '';

          if (attrs.kind === 'insertion') {
            if (newValueText.length === 0) return false;
            const insertedFrom = from;
            const insertedTo = from + newValueText.length;
            tr.insert(insertedFrom, state.schema.text(newValueText));
            tr.addMark(insertedFrom, insertedTo, wrappingMark);
            tr.addMark(insertedFrom, insertedTo, ins.create());
          } else if (attrs.kind === 'deletion') {
            if (from === to) return false;
            tr.addMark(from, to, wrappingMark);
            tr.addMark(from, to, del.create());
          } else {
            if (from === to) return false;
            const oldFrom = from;
            const oldTo = to;
            const newFrom = oldTo;
            const newLen = newValueText.length;

            if (newLen > 0) {
              tr.insert(newFrom, state.schema.text(newValueText));
            }
            const newTo = newFrom + newLen;

            tr.addMark(oldFrom, newTo, wrappingMark);
            tr.addMark(oldFrom, oldTo, del.create());
            if (newLen > 0) {
              tr.addMark(newFrom, newTo, ins.create());
            }
          }

          tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
          if (dispatch) dispatch(tr);
          return true;
        },

      replaceWithNewValueById:
        (suggestionId) =>
        ({ state, tr, dispatch }) => {
          const ranges = findSuggestionRangesById(state.doc, suggestionId);
          if (ranges.wrapping.length === 0) return false;

          const wrap = state.schema.marks[SUGGESTION_MARK];
          const ins = state.schema.marks[SUGGESTION_INSERTION_MARK];

          // Format-change branch: just drop the wrapping mark.
          // The proposed format mark (or its absence) was already applied
          // when the user made the edit; accept = leave it as-is.
          const wrappingMark = ranges.wrapping[0].mark;
          if (wrappingMark.attrs.formatOp) {
            const wrappingMerged = mergeAdjacent(ranges.wrapping);
            for (const r of [...wrappingMerged].reverse()) {
              if (wrap) tr.removeMark(r.from, r.to, wrap);
            }
            tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
            if (dispatch) dispatch(tr);
            return true;
          }

          const deletion = mergeAdjacent(ranges.deletion);
          const insertion = mergeAdjacent(ranges.insertion);

          for (const r of [...insertion].reverse()) {
            if (wrap) tr.removeMark(r.from, r.to, wrap);
            if (ins) tr.removeMark(r.from, r.to, ins);
          }
          for (const r of [...deletion].reverse()) {
            tr.delete(r.from, r.to);
          }

          tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
          if (dispatch) dispatch(tr);
          return true;
        },

      removeMarkById:
        (suggestionId) =>
        ({ state, tr, dispatch }) => {
          const ranges = findSuggestionRangesById(state.doc, suggestionId);
          if (ranges.wrapping.length === 0) return false;

          const wrap = state.schema.marks[SUGGESTION_MARK];
          const del = state.schema.marks[SUGGESTION_DELETION_MARK];

          // Format-change branch: revert the proposed format op and drop wrapping.
          const wrappingMark = ranges.wrapping[0].mark;
          const formatOp = wrappingMark.attrs.formatOp as
            | { markName: string; attrs: Record<string, unknown>; op: 'add' | 'remove' }
            | null;
          if (formatOp) {
            const wrappingMerged = mergeAdjacent(ranges.wrapping);
            const formatMarkType = state.schema.marks[formatOp.markName];
            for (const r of [...wrappingMerged].reverse()) {
              if (formatMarkType) {
                if (formatOp.op === 'add') {
                  // Reject add → strip the proposed format mark.
                  tr.removeMark(r.from, r.to, formatMarkType);
                } else {
                  // Reject remove → re-apply the format mark with original attrs.
                  tr.addMark(r.from, r.to, formatMarkType.create(formatOp.attrs));
                }
              }
              if (wrap) tr.removeMark(r.from, r.to, wrap);
            }
            tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
            if (dispatch) dispatch(tr);
            return true;
          }

          const insertion = mergeAdjacent(ranges.insertion);
          const deletion = mergeAdjacent(ranges.deletion);

          for (const r of [...deletion].reverse()) {
            if (wrap) tr.removeMark(r.from, r.to, wrap);
            if (del) tr.removeMark(r.from, r.to, del);
          }
          for (const r of [...insertion].reverse()) {
            tr.delete(r.from, r.to);
          }

          tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
          if (dispatch) dispatch(tr);
          return true;
        },

      promotePendingCluster:
        (pendingId, next) =>
        ({ state, tr, dispatch }) => {
          const ranges = findSuggestionRangesByPendingId(state.doc, pendingId);
          if (ranges.wrapping.length === 0) return false;

          const wrap = state.schema.marks[SUGGESTION_MARK];
          if (!wrap) return false;

          const merged = mergeAdjacent(ranges.wrapping);
          for (const r of [...merged].reverse()) {
            const oldMark = r.mark;
            const newAttrs = {
              ...oldMark.attrs,
              suggestionId: next.suggestionId,
              targetId: next.targetId,
              kind: next.kind,
              oldValue: next.oldValue,
              newValue: next.newValue,
            };
            tr.removeMark(r.from, r.to, wrap);
            tr.addMark(r.from, r.to, wrap.create(newAttrs));
          }

          tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
          tr.setMeta('addToHistory', false);
          if (dispatch) dispatch(tr);
          return true;
        },

      setSuggestionPluginEnabled:
        (enabled) =>
        ({ tr, dispatch }) => {
          if (dispatch) {
            tr.setMeta(suggestionPluginKey, {
              type: META_SET_STATE,
              payload: { enabled },
            });
            dispatch(tr);
          }
          return true;
        },

      setSuggestionPluginAuthor:
        (author) =>
        ({ tr, dispatch }) => {
          if (dispatch) {
            tr.setMeta(suggestionPluginKey, {
              type: META_SET_STATE,
              payload: { currentUser: author },
            });
            dispatch(tr);
          }
          return true;
        },
    };
  },
});

export const SuggestionExtensions = (options: Partial<SuggestionMetaOptions> = {}) => [
  // Order matters — SuggestionMark first → outermost in renderHTML nesting.
  SuggestionMark,
  SuggestionDeletionMark,
  SuggestionInsertionMark,
  SuggestionMeta.configure(options),
];

inlineCorePluginContent:
import { Plugin, PluginKey } from '@tiptap/pm/state';
import type { EditorState, Transaction } from '@tiptap/pm/state';
import { AddMarkStep, RemoveMarkStep, ReplaceStep } from '@tiptap/pm/transform';
import { Fragment, Slice } from '@tiptap/pm/model';
import type { Mark as PMMark, MarkType, Node as PMNode } from '@tiptap/pm/model';
import type { FormatOp, SuggestionAuthor } from './types';
import {
  SUGGESTION_DELETION_MARK,
  SUGGESTION_INSERTION_MARK,
  SUGGESTION_MARK,
  pendingMarkAtPos,
  rangeOverlapsCommitted,
} from './suggestionMark';

export interface SuggestionPluginState {
  enabled: boolean;
  currentUser: SuggestionAuthor | null;
  trackedFormatMarks: ReadonlySet<string>;
}

export const suggestionPluginKey = new PluginKey<SuggestionPluginState>(
  'veltSuggestionInline',
);

export const META_SKIP = 'skip';
export const META_SET_STATE = 'setState';

function newPendingId(): string {
  const rand =
    typeof crypto !== 'undefined' && crypto.randomUUID
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `pending:${rand}`;
}

function buildPendingWrappingAttrs(
  author: SuggestionAuthor,
  pendingId: string,
  baseTimestamp?: number,
  formatOp: FormatOp | null = null,
) {
  return {
    pendingId,
    suggestionId: null,
    targetId: null,
    kind: formatOp ? (`format-${formatOp.op}` as const) : ('pending' as const),
    oldValue: '',
    newValue: '',
    formatOp,
    userId: author.userId,
    userName: author.name,
    color: author.color,
    timestamp: baseTimestamp ?? Date.now(),
  };
}

const SUGGESTION_MARK_NAMES: ReadonlySet<string> = new Set([
  SUGGESTION_MARK,
  SUGGESTION_DELETION_MARK,
  SUGGESTION_INSERTION_MARK,
]);

function isFormatStep(step: unknown): step is AddMarkStep | RemoveMarkStep {
  return step instanceof AddMarkStep || step instanceof RemoveMarkStep;
}

function isAllOwnPendingInsertion(
  slice: Slice,
  insertionType: MarkType,
  wrappingType: MarkType,
  userId: string,
): boolean {
  let allOwn = true;
  let hasInline = false;
  slice.content.descendants((node) => {
    if (!allOwn) return false;
    if (node.isText) {
      hasInline = true;
      const ins = node.marks.find((m) => m.type === insertionType);
      const wrap = node.marks.find((m) => m.type === wrappingType);
      if (!ins || !wrap) {
        allOwn = false;
        return false;
      }
      if (wrap.attrs.userId !== userId || wrap.attrs.suggestionId) {
        allOwn = false;
        return false;
      }
    }
    return true;
  });
  return hasInline && allOwn;
}

function remapSliceForDeletion(
  slice: Slice,
  insertionType: MarkType,
  deletionType: MarkType,
  wrappingType: MarkType,
  wrappingAttrs: Record<string, unknown>,
): Slice {
  const visit = (frag: Fragment): Fragment => {
    const out: PMNode[] = [];
    frag.forEach((node) => {
      const cleaned = node.marks.filter(
        (m) =>
          m.type !== insertionType &&
          m.type !== deletionType &&
          m.type !== wrappingType,
      );
      const newMarks = cleaned.concat(
        wrappingType.create(wrappingAttrs),
        deletionType.create(),
      );
      if (node.isText) {
        out.push(node.mark(newMarks));
      } else {
        out.push(node.copy(visit(node.content)).mark(newMarks));
      }
    });
    return Fragment.from(out);
  };
  return new Slice(visit(slice.content), slice.openStart, slice.openEnd);
}

export function createInlineSuggestionPlugin() {
  return new Plugin<SuggestionPluginState>({
    key: suggestionPluginKey,

    state: {
      init: () => ({
        enabled: false,
        currentUser: null,
        trackedFormatMarks: new Set<string>([
          'bold',
          'italic',
          'strike',
          'code',
          'underline',
        ]),
      }),
      apply(tr, prev) {
        const meta = tr.getMeta(suggestionPluginKey);
        if (meta && meta.type === META_SET_STATE) {
          return { ...prev, ...meta.payload };
        }
        return prev;
      },
    },

    filterTransaction(tr, state) {
      const ps = suggestionPluginKey.getState(state);
      if (tr.getMeta(suggestionPluginKey)?.[META_SKIP]) return true;
      // Undo/redo transactions reverse already-applied edits; they must always
      // pass through the lock, otherwise users can't undo edits that have
      // since been committed (their reversal steps overlap committed ranges).
      if (tr.getMeta('history$')) return true;
      if (!ps?.enabled || !ps.currentUser) return true;
      for (const step of tr.steps) {
        if (step instanceof ReplaceStep) {
          const rs = step as unknown as { from: number; to: number };
          if (rangeOverlapsCommitted(state.doc, rs.from, rs.to)) {
            return false;
          }
        } else if (isFormatStep(step)) {
          const fs = step as unknown as { from: number; to: number; mark: PMMark };
          if (SUGGESTION_MARK_NAMES.has(fs.mark.type.name)) continue;
          if (rangeOverlapsCommitted(state.doc, fs.from, fs.to)) {
            return false;
          }
        }
      }
      return true;
    },

  });
}

/**
 * Mutates `tr` (which already carries the user's steps) by appending the
 * wrapping/insertion/deletion mark operations needed to track the edit as a
 * suggestion. Returns true if anything was added.
 *
 * This is invoked from the Tiptap extension's dispatch wrapper so the user's
 * steps and our marking steps land in PM as a SINGLE transaction — giving
 * atomic undo/redo for free.
 */
export function applySuggestionRewrite(
  tr: Transaction,
  oldState: EditorState,
  ps: SuggestionPluginState,
): boolean {
  if (!ps.enabled || !ps.currentUser) return false;
  if (tr.getMeta(suggestionPluginKey)?.[META_SKIP]) return false;
  if (tr.getMeta('history$')) return false;
  if (!tr.docChanged) return false;

  const wrappingType = oldState.schema.marks[SUGGESTION_MARK];
  const insertionType = oldState.schema.marks[SUGGESTION_INSERTION_MARK];
  const deletionType = oldState.schema.marks[SUGGESTION_DELETION_MARK];
  if (!wrappingType || !insertionType || !deletionType) return false;

  const author = ps.currentUser;

  // Snapshot the user's portion of the transaction. We append our own steps
  // afterwards; tr.mapping grows to include both.
  const userStepCount = tr.steps.length;
  type StepCtx = { step: ReplaceStep; pre: PMNode; idx: number };
  const linear: StepCtx[] = [];
  let runningDoc: PMNode = oldState.doc;
  for (let i = 0; i < userStepCount; i++) {
    const step = tr.steps[i];
    if (step instanceof ReplaceStep) {
      linear.push({ step, pre: runningDoc, idx: i });
    }
    runningDoc = tr.docs[i + 1] ?? tr.doc;
  }

  let modified = false;

  for (const { step, pre, idx } of linear) {
    const rs = step as unknown as { from: number; to: number; slice: Slice };
    const stepFrom = rs.from;
    const stepTo = rs.to;
    const slice = rs.slice;
    const insertedSize = slice.size;
    const deletedSize = stepTo - stepFrom;
    if (insertedSize === 0 && deletedSize === 0) continue;

    // Map the step's pre-doc position through every step that came after it
    // (later user steps + any of our additions so far)
    const mappedFrom = tr.mapping.slice(idx + 1).map(stepFrom);

    const neighbor = pendingMarkAtPos(tr.doc, mappedFrom, author.userId);
    const pendingId = neighbor?.pendingId ?? newPendingId();
    const baseTimestamp = neighbor?.mark.attrs.timestamp as number | undefined;
    const wrappingAttrs = buildPendingWrappingAttrs(author, pendingId, baseTimestamp);

    if (insertedSize > 0) {
      const insertedFrom = mappedFrom;
      const insertedTo = insertedFrom + insertedSize;
      tr.removeMark(insertedFrom, insertedTo, wrappingType);
      tr.removeMark(insertedFrom, insertedTo, insertionType);
      tr.removeMark(insertedFrom, insertedTo, deletionType);
      tr.addMark(insertedFrom, insertedTo, wrappingType.create(wrappingAttrs));
      tr.addMark(insertedFrom, insertedTo, insertionType.create());
      modified = true;
    }

    if (deletedSize > 0) {
      const deletedSlice = pre.slice(stepFrom, stepTo);
      if (deletedSlice.openStart > 0 || deletedSlice.openEnd > 0) continue;
      if (isAllOwnPendingInsertion(deletedSlice, insertionType, wrappingType, author.userId)) {
        continue;
      }
      const remarked = remapSliceForDeletion(
        deletedSlice,
        insertionType,
        deletionType,
        wrappingType,
        wrappingAttrs,
      );
      const insertAt = tr.mapping.slice(idx + 1).map(stepFrom);
      tr.replace(insertAt, insertAt, remarked);
      modified = true;
    }
  }

  // Phase 3a: pure-format transactions (only AddMarkStep / RemoveMarkStep,
  // no ReplaceStep among the user's steps). Apply wrapping mark on the
  // affected range so the format toggle is tracked as a suggestion.
  let userHasReplace = false;
  let userHasFormat = false;
  for (let i = 0; i < userStepCount; i++) {
    const s = tr.steps[i];
    if (s instanceof ReplaceStep) userHasReplace = true;
    if (isFormatStep(s)) userHasFormat = true;
  }
  if (!userHasReplace && userHasFormat) {
    const tracked = ps.trackedFormatMarks;
    for (let i = 0; i < userStepCount; i++) {
      const step = tr.steps[i];
      if (!isFormatStep(step)) continue;
      const fs = step as unknown as { from: number; to: number; mark: PMMark };
      if (fs.from === fs.to) continue;
      if (SUGGESTION_MARK_NAMES.has(fs.mark.type.name)) continue;
      if (tracked.size > 0 && !tracked.has(fs.mark.type.name)) continue;

      const op: 'add' | 'remove' = step instanceof AddMarkStep ? 'add' : 'remove';
      const formatOp: FormatOp = {
        markName: fs.mark.type.name,
        attrs: fs.mark.attrs ?? {},
        op,
      };
      const fromMapped = tr.mapping.slice(i + 1).map(fs.from);
      const toMapped = tr.mapping.slice(i + 1).map(fs.to);
      if (fromMapped >= toMapped) continue;

      const neighbor = pendingMarkAtPos(tr.doc, fromMapped, author.userId);
      const pendingId = neighbor?.pendingId ?? newPendingId();
      const baseTimestamp = neighbor?.mark.attrs.timestamp as number | undefined;
      const wrappingAttrs = buildPendingWrappingAttrs(author, pendingId, baseTimestamp, formatOp);
      tr.addMark(fromMapped, toMapped, wrappingType.create(wrappingAttrs));
      modified = true;
    }
  }

  if (!modified) return false;
  tr.setMeta(suggestionPluginKey, { [META_SKIP]: true });
  return true;
}

inlineCoreSuggestionMarkContent:
import { Mark, mergeAttributes } from '@tiptap/core';
import type { Mark as PMMark, Node as PMNode } from '@tiptap/pm/model';
import type { FormatOp, SuggestionKind, SuggestionMarkAttrs } from './types';

export const SUGGESTION_MARK = 'veltSuggestion';
export const SUGGESTION_DELETION_MARK = 'veltSuggestionDeletion';
export const SUGGESTION_INSERTION_MARK = 'veltSuggestionInsertion';

const wrappingAttrSpec = {
  pendingId: { default: '', rendered: false },
  suggestionId: { default: null as string | null, rendered: false },
  targetId: { default: null as string | null, rendered: false },
  kind: { default: 'pending' as SuggestionKind, rendered: false },
  oldValue: { default: '', rendered: false },
  newValue: { default: '', rendered: false },
  formatOp: { default: null as FormatOp | null, rendered: false },
  userId: { default: null as string | null, rendered: false },
  userName: { default: null as string | null, rendered: false },
  color: { default: '#1976d2', rendered: false },
  timestamp: { default: 0, rendered: false },
};

const renderWrappingDataAttrs = (attrs: SuggestionMarkAttrs) => {
  const committed = !!attrs.suggestionId;
  return {
    // The data-velt-suggestion-target attribute is part of Velt's protocol for
    // DOM-level target resolution. Renaming would break the integration; the
    // attribute lives here even though the mark itself is generic.
    'data-velt-suggestion-target': attrs.targetId ?? attrs.suggestionId ?? '',
    'data-velt-suggestion-id': attrs.suggestionId ?? '',
    'data-velt-pending-id': attrs.pendingId ?? '',
    'data-velt-suggestion-kind': attrs.kind,
    'data-velt-state': committed ? 'committed' : 'pending',
    'data-velt-format-op': attrs.formatOp ? JSON.stringify(attrs.formatOp) : '',
    'data-user-id': attrs.userId,
    'data-user-name': attrs.userName,
    'data-color': attrs.color,
    'data-timestamp': String(attrs.timestamp),
    style: `--velt-suggestion-color: ${attrs.color}`,
    class: `velt-suggestion ${committed ? 'velt-suggestion-committed' : 'velt-suggestion-pending'}`,
  };
};

const parseWrappingDataAttrs = (el: HTMLElement) => {
  const targetId =
    el.getAttribute('data-velt-suggestion-target') ??
    el.getAttribute('data-velt-target-id') ??
    null;
  const suggestionId = el.getAttribute('data-velt-suggestion-id') || null;
  let formatOp: FormatOp | null = null;
  const rawFormatOp = el.getAttribute('data-velt-format-op');
  if (rawFormatOp) {
    try {
      formatOp = JSON.parse(rawFormatOp) as FormatOp;
    } catch {
      formatOp = null;
    }
  }
  const attrs: Partial<SuggestionMarkAttrs> = {
    pendingId: el.getAttribute('data-velt-pending-id') ?? '',
    suggestionId,
    targetId,
    kind: (el.getAttribute('data-velt-suggestion-kind') as SuggestionKind) ?? 'pending',
    formatOp,
    userId: el.getAttribute('data-user-id') ?? null,
    userName: el.getAttribute('data-user-name') ?? null,
    color: el.getAttribute('data-color') ?? '#1976d2',
    timestamp: Number(el.getAttribute('data-timestamp')) || 0,
  };
  return attrs;
};

/**
 * Wrapping mark — carries the suggestion identity. Applied to the full range
 * spanning both the deletion and insertion halves so PM mark-merging renders
 * a single outer span. Declared first so it nests outside the inner kind marks.
 */
export const SuggestionMark = Mark.create({
  name: SUGGESTION_MARK,
  inclusive: false,
  excludes: '',
  spanning: true,

  addAttributes() {
    return wrappingAttrSpec;
  },

  parseHTML() {
    return [
      {
        tag: 'span[data-velt-suggestion-target]',
        getAttrs: (node) => parseWrappingDataAttrs(node as HTMLElement),
      },
      {
        tag: 'span[data-velt-suggestion-id]',
        getAttrs: (node) => parseWrappingDataAttrs(node as HTMLElement),
      },
    ];
  },

  renderHTML({ mark, HTMLAttributes }) {
    const attrs = mark.attrs as SuggestionMarkAttrs;
    return [
      'span',
      mergeAttributes(HTMLAttributes, renderWrappingDataAttrs(attrs)),
      0,
    ];
  },
});

export const SuggestionDeletionMark = Mark.create({
  name: SUGGESTION_DELETION_MARK,
  inclusive: false,
  excludes: '',
  spanning: true,

  parseHTML() {
    return [{ tag: 'span[data-velt-suggestion-kind="deletion"]' }];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      'span',
      mergeAttributes(HTMLAttributes, {
        'data-velt-suggestion-kind': 'deletion',
        class: 'velt-suggestion-deletion',
      }),
      0,
    ];
  },
});

export const SuggestionInsertionMark = Mark.create({
  name: SUGGESTION_INSERTION_MARK,
  inclusive: false,
  excludes: '',
  spanning: true,

  parseHTML() {
    return [{ tag: 'span[data-velt-suggestion-kind="insertion"]' }];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      'span',
      mergeAttributes(HTMLAttributes, {
        'data-velt-suggestion-kind': 'insertion',
        class: 'velt-suggestion-insertion',
      }),
      0,
    ];
  },
});

export interface MarkRange {
  from: number;
  to: number;
  mark: PMMark;
}

interface SuggestionRanges {
  wrapping: MarkRange[];
  deletion: MarkRange[];
  insertion: MarkRange[];
}

function rangesByPredicate(
  doc: PMNode,
  predicate: (mark: PMMark) => boolean,
): SuggestionRanges {
  const out: SuggestionRanges = { wrapping: [], deletion: [], insertion: [] };
  doc.descendants((node, pos) => {
    if (!node.isInline) return true;
    const wrap = node.marks.find(
      (m) => m.type.name === SUGGESTION_MARK && predicate(m),
    );
    if (!wrap) return true;
    const range: MarkRange = { from: pos, to: pos + node.nodeSize, mark: wrap };
    out.wrapping.push(range);
    if (node.marks.some((m) => m.type.name === SUGGESTION_DELETION_MARK)) {
      out.deletion.push(range);
    }
    if (node.marks.some((m) => m.type.name === SUGGESTION_INSERTION_MARK)) {
      out.insertion.push(range);
    }
    return true;
  });
  return out;
}

export function findSuggestionRangesById(
  doc: PMNode,
  suggestionId: string,
): SuggestionRanges {
  return rangesByPredicate(doc, (m) => m.attrs.suggestionId === suggestionId);
}

export function findSuggestionRangesByPendingId(
  doc: PMNode,
  pendingId: string,
): SuggestionRanges {
  return rangesByPredicate(doc, (m) => m.attrs.pendingId === pendingId);
}

export interface PendingClusterSummary {
  pendingId: string;
  userId: string | null;
  userName: string | null;
  color: string;
  timestamp: number;
  hasDeletion: boolean;
  hasInsertion: boolean;
  formatOp: FormatOp | null;
  ranges: SuggestionRanges;
}

export function listPendingClusters(doc: PMNode): PendingClusterSummary[] {
  const seen = new Map<string, PendingClusterSummary>();
  doc.descendants((node) => {
    if (!node.isInline) return true;
    for (const m of node.marks) {
      if (m.type.name !== SUGGESTION_MARK) continue;
      if (m.attrs.suggestionId) continue;
      const pid = m.attrs.pendingId as string;
      if (!pid || seen.has(pid)) continue;
      seen.set(pid, {
        pendingId: pid,
        userId: m.attrs.userId ?? null,
        userName: m.attrs.userName ?? null,
        color: m.attrs.color ?? '#1976d2',
        timestamp: m.attrs.timestamp ?? 0,
        hasDeletion: false,
        hasInsertion: false,
        formatOp: (m.attrs.formatOp as FormatOp | null) ?? null,
        ranges: { wrapping: [], deletion: [], insertion: [] },
      });
    }
    return true;
  });
  for (const summary of seen.values()) {
    summary.ranges = findSuggestionRangesByPendingId(doc, summary.pendingId);
    summary.hasDeletion = summary.ranges.deletion.length > 0;
    summary.hasInsertion = summary.ranges.insertion.length > 0;
  }
  return Array.from(seen.values());
}

export function listCommittedSuggestionIds(doc: PMNode): string[] {
  const ids = new Set<string>();
  doc.descendants((node) => {
    if (!node.isInline) return true;
    for (const m of node.marks) {
      if (m.type.name === SUGGESTION_MARK && m.attrs.suggestionId) {
        ids.add(m.attrs.suggestionId);
      }
    }
    return true;
  });
  return Array.from(ids);
}

function mergeAdjacent(ranges: MarkRange[]): MarkRange[] {
  if (ranges.length === 0) return ranges;
  const sorted = [...ranges].sort((a, b) => a.from - b.from);
  const out: MarkRange[] = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const prev = out[out.length - 1];
    const cur = sorted[i];
    if (cur.from === prev.to) {
      out[out.length - 1] = { from: prev.from, to: cur.to, mark: prev.mark };
    } else {
      out.push(cur);
    }
  }
  return out;
}

function textOfRanges(doc: PMNode, ranges: MarkRange[]): string {
  if (ranges.length === 0) return '';
  return mergeAdjacent(ranges)
    .map((r) => doc.textBetween(r.from, r.to, ' ', ' '))
    .join('');
}

export function deletionTextById(doc: PMNode, suggestionId: string): string {
  return textOfRanges(doc, findSuggestionRangesById(doc, suggestionId).deletion);
}

export function insertionTextById(doc: PMNode, suggestionId: string): string {
  return textOfRanges(doc, findSuggestionRangesById(doc, suggestionId).insertion);
}

export function wrappingTextById(doc: PMNode, suggestionId: string): string {
  return textOfRanges(doc, findSuggestionRangesById(doc, suggestionId).wrapping);
}

export function formatOpById(doc: PMNode, suggestionId: string): FormatOp | null {
  const ranges = findSuggestionRangesById(doc, suggestionId);
  if (ranges.wrapping.length === 0) return null;
  return (ranges.wrapping[0].mark.attrs.formatOp as FormatOp | null) ?? null;
}

export function pendingClusterText(doc: PMNode, pendingId: string) {
  const ranges = findSuggestionRangesByPendingId(doc, pendingId);
  return {
    oldValue: textOfRanges(doc, ranges.deletion),
    newValue: textOfRanges(doc, ranges.insertion),
    wrappingText: textOfRanges(doc, ranges.wrapping),
    ranges,
  };
}

export function pendingMarkAtPos(
  doc: PMNode,
  pos: number,
  userId: string | null,
): { pendingId: string; mark: PMMark } | null {
  if (pos < 0) return null;
  const docSize = doc.content.size;
  const probes: number[] = [];
  if (pos > 0 && pos - 1 <= docSize) probes.push(pos - 1);
  if (pos < docSize) probes.push(pos);

  for (const p of probes) {
    let result: { pendingId: string; mark: PMMark } | null = null;
    doc.nodesBetween(p, Math.min(p + 1, docSize), (node) => {
      if (result) return false;
      if (!node.isInline) return true;
      const m = node.marks.find(
        (mk) =>
          mk.type.name === SUGGESTION_MARK &&
          !mk.attrs.suggestionId &&
          (userId == null || mk.attrs.userId === userId),
      );
      if (m && m.attrs.pendingId) {
        result = { pendingId: m.attrs.pendingId, mark: m };
        return false;
      }
      return true;
    });
    if (result) return result;
  }
  return null;
}

export function rangeOverlapsCommitted(doc: PMNode, from: number, to: number): boolean {
  if (from === to) return false;
  let hit = false;
  doc.nodesBetween(from, to, (node) => {
    if (hit) return false;
    if (!node.isInline) return true;
    if (
      node.marks.some(
        (m) => m.type.name === SUGGESTION_MARK && !!m.attrs.suggestionId,
      )
    ) {
      hit = true;
      return false;
    }
    return true;
  });
  return hit;
}

export { mergeAdjacent };

